def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    diff = {}
    for k, v in d1.items():
        if k not in d2:
            diff[k] = v
        elif isinstance(v, dict):
            if level == -1:
                diff[k] = v
            else:
                diff[k] = difference(v, d2[k], level - 1)
        elif v != d2[k]:
            diff[k] = v
    return diff
