        if not isinstance(fixity_info, dict):
            raise ValueError(f"Invalid fixity information for file '{file_path}': not a dictionary")
        if not fixity_info.get('hashes'):
            raise ValueError(f"Missing hashes in fixity information for file '{file_path}'")
        for algorithm, hash_value in fixity_info['hashes'].items():
