def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for subparser_name, subparser in subparsers.items():
        try:
            result, unclaimed_args = subparser.parse_known_args(unparsed_arguments)
        except SystemExit:
            continue
        parsed_args[subparser_name] = result
        remaining_args.extend(unclaimed_args)
