def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        if isinstance(node, ruamel.yaml.nodes.ScalarNode):
            result.append(node)
        else:
            key = node[0]
            value = node[1]
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged = deep_merge_nodes([(key, v) for v in value])
                result.append((key, merged))
            else:
                result.append(node)
    return result
