def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency")
    number = int(parts[0])
    unit = parts[1].lower()
    if unit == "week":
        delta = datetime.timedelta(weeks=number)
    elif unit == "day":
        delta = datetime.timedelta(days=number)
    elif unit == "hour":
        delta = datetime.timedelta(hours=number)
    elif unit == "minute":
        delta = datetime.timedelta(minutes=number)
    elif unit == "second":
        delta = datetime.timedelta(seconds=number)
    else:
        raise ValueError("Invalid frequency unit")
    return delta
