def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise ValueError("ticks must be an int")
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    hour = ticks // 3600000000000
    minute = (ticks % 3600000000000) // 60000000000
    second = (ticks % 60000000000) // 1000000000
    nanosecond = ticks % 1000000000
    if tz is None:
        return cls(hour, minute, second, nanosecond)
    else:
        return cls(hour, minute, second, nanosecond, tzinfo=tz)
