def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content
    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    if len(field_names) != 2:
        raise ValueError("field_names must have two elements")

    # Prepare the data
    hist_content = hist.content()
    hist_bins = hist.bins()
    hist_errors = hist.errors()
    if make_value is not None:
        hist_content = [make_value(h) for h in hist_content]

    # Create the graph
    graph = Graph()
    for i, (h, err) in enumerate(zip(hist_content, hist_errors)):
        coord = get_coordinate
        if coord == "left":
            x = hist_bins.start(i)
        elif coord == "right":
            x = hist_bins.end(i)
        elif coord == "middle":
            x = hist_bins.middle(i)
        y = h
        graph.add_point((x, y))

    # Set the graph scale
    if scale is None:
        graph.scale = scales.LinearScale()
    elif isinstance(scale, (int, float)):
        graph.scale = scales.LinearScale(scala=scale)
    else:
        graph.scale = scales.LogScale()

    # Set the graph field names
    graph.field_names = field_names

    return graph

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"The candidate {candidate} does not provide the interface {iface}")

    # Check that the candidate defines all the necessary methods
    for name, method in iface:
        if not hasattr(candidate, name):
            raise Invalid(f"The candidate {candidate} does not define the method {name}")
        if not hasattr(candidate, name) == method:
            raise Invalid(f"The candidate {candidate} does not have the correct signature for the method {name}")

    # Check that the candidate defines all the necessary attributes
    for name, attribute in iface.getAttributeDescriptions():
        if not hasattr(candidate, name):
            raise Invalid(f"The candidate {candidate} does not define the attribute {name}")

    return True

