def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for arg_name, arg_value in values_dict.items():
        arg_type = self.get_arg_type(parser_name, arg_name)
        if arg_type is not None:
            try:
                values_dict[arg_name] = arg_type(arg_value)
            except ValueError:
                pass
[/PYTHON]

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import yaml
    from collections import defaultdict

    flat_dict = defaultdict(list)

    with open(os.path.join(plugin_dir, 'plugin.yaml'), 'r') as f:
        plugin_spec = yaml.safe_load(f.read())

    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            flat_dict['{}.{}'.format(key, k)] = v for k, v in value.items()
        else:
            flat_dict[key] = value

    return dict(flat_dict)

